import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-02","description":"","frontmatter":{"title":"AI 动态 · 2026-11-02","date":"2026-11-02T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-02.md","filePath":"news/2026-11/ai-news-2026-11-02.md","lastUpdated":null}'),r={name:"news/2026-11/ai-news-2026-11-02.md"};function o(i,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-11-02" tabindex="-1">AI 动态 · 2026-11-02 <a class="header-anchor" href="#ai-动态-·-2026-11-02" aria-label="Permalink to &quot;AI 动态 · 2026-11-02&quot;">​</a></h1><blockquote><p>截至 2026-11-02。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="omen-ai-以-1600-万美元收购-aquatic-labs-补足液冷能力" tabindex="-1">Omen AI 以 1600 万美元收购 Aquatic Labs，补足液冷能力 <a class="header-anchor" href="#omen-ai-以-1600-万美元收购-aquatic-labs-补足液冷能力" aria-label="Permalink to &quot;Omen AI 以 1600 万美元收购 Aquatic Labs，补足液冷能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-02">2026-11-02</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/eb72ce315af3.webp" alt="配图"></p><p>两家都在解决数据中心用水问题的初创公司合并，Omen AI 以 1600 万美元收购 Aquatic Labs，把液冷相关技术纳入自身方案。在算力园区能耗与水资源争议升温的背景下，散热与用水正成为 AI 基建的并购热点。对读者：关注数据中心散热赛道的读者，可把液冷/节水技术供应商列入观察名单。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/02/omen-ai-adds-liquid-know-how-in-16-million-aquatic-labs-acquisition/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-或把数据中心改称「ai-算力园区」" tabindex="-1">OpenAI 或把数据中心改称「AI 算力园区」 <a class="header-anchor" href="#openai-或把数据中心改称「ai-算力园区」" aria-label="Permalink to &quot;OpenAI 或把数据中心改称「AI 算力园区」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-02">2026-11-02</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/3cc0516ee393.jpg" alt="配图"></p><p>面对数据中心日益不受欢迎的舆论环境，OpenAI 考虑将旗下设施重新命名为「AI compute campuses」。改名本身不解决能耗与选址争议，但反映出 AI 基建正在经历一场叙事与公共关系的重塑。对读者：地方政策与社区沟通可能成为算力项目落地的新变量，值得纳入风险清单。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/01/openai-might-rebrand-its-data-centers-as-ai-compute-campuses/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai-推出-grid-protectors-计划-让算力园区反哺电网" tabindex="-1">OpenAI 推出 Grid Protectors 计划，让算力园区反哺电网 <a class="header-anchor" href="#openai-推出-grid-protectors-计划-让算力园区反哺电网" aria-label="Permalink to &quot;OpenAI 推出 Grid Protectors 计划，让算力园区反哺电网&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-02">2026-11-02</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/9ea484054107.webp" alt="配图"></p><p>OpenAI 宣布启动 Grid Protectors 全国性计划，与电力公司合作，使未来新建的算力园区在用电高峰时支持电网可靠性，并保护居民电价不被推高。这既是应对数据中心能耗舆论的公关动作，也意味着算力扩张开始被纳入能源基础设施协同框架。对读者：若你关注 AI 基建成本，可跟进该计划是否带来电价分摊或并网审批上的实质变化。</p><p class="news-entry-source"><a href="https://openai.com/index/grid-protectors-program" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="chatgpt-合并-chat-与-work-标签页-与-codex-共用额度池" tabindex="-1">ChatGPT 合并 Chat 与 Work 标签页，与 Codex 共用额度池 <a class="header-anchor" href="#chatgpt-合并-chat-与-work-标签页-与-codex-共用额度池" aria-label="Permalink to &quot;ChatGPT 合并 Chat 与 Work 标签页，与 Codex 共用额度池&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-02">2026-11-02</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/0532bed5c2d7.jpg" alt="配图"></p><p>OpenAI 将 ChatGPT 的 Chat 与 Work 两个标签页合并，并说明此后 ChatGPT 与 Codex 的使用量从同一额度池中扣除。对重度用户而言，这意味着写代码与日常对话会互相挤占配额，套餐选择需要重新算账。对读者：团队采购前先统计 Chat 与 Codex 的实际消耗比例，避免合并计费后某一侧被意外限流。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/02/openai-is-finally-merging-chatgpts-chat-and-work-tabs/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="openai-发布-lifeval-基准-衡量-ai-处理日常事务的能力" tabindex="-1">OpenAI 发布 LifeVal 基准，衡量 AI 处理日常事务的能力 <a class="header-anchor" href="#openai-发布-lifeval-基准-衡量-ai-处理日常事务的能力" aria-label="Permalink to &quot;OpenAI 发布 LifeVal 基准，衡量 AI 处理日常事务的能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-02">2026-11-02</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/a8416b03ea79.png" alt="配图"></p><p>LifeVal 是一个新基准，用来评估 AI 在找托育、管理财务、处理政府文书等日常任务上到底帮人帮到什么程度，而非只测考试题。它把评测重心从「知识问答」推向「真实生活任务完成度」，对产品选型有参考价值。对读者：评估模型时不妨用自己业务里的高频琐事做小样本测试，比看榜单更贴近实际体验。</p><p class="news-entry-source"><a href="https://openai.com/index/lifeval" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-messages-api-上线-message-threads-加速长时-agent" tabindex="-1">Claude Messages API 上线 message threads，加速长时 Agent <a class="header-anchor" href="#claude-messages-api-上线-message-threads-加速长时-agent" aria-label="Permalink to &quot;Claude Messages API 上线 message threads，加速长时 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-02">2026-11-02</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/b1494b40196f.webp" alt="配图"></p><p>Anthropic 在 Messages API 中新增 message threads：会话只需发送一次，之后每轮 API 仅接收新增内容。这对长时间运行的 Agent 意义明显，可减少重复传输的上下文、降低延迟与 token 开销。对读者：若你在做多轮 Agent，可评估迁移到该机制，重点测试增量上下文与工具调用状态是否保持一致。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/message-threads" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="nvidia-开源-auto-ontology-为-agent-写-sql-提供语义层" tabindex="-1">NVIDIA 开源 Auto Ontology：为 Agent 写 SQL 提供语义层 <a class="header-anchor" href="#nvidia-开源-auto-ontology-为-agent-写-sql-提供语义层" aria-label="Permalink to &quot;NVIDIA 开源 Auto Ontology：为 Agent 写 SQL 提供语义层&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-02">2026-11-02</time></p><p>NVIDIA 发布 Apache 2.0 许可的 Auto Ontology，可从企业元数据自动生成语义层，让 Agent 生成的 SQL 锚定在已认证的定义上，并通过 MCP、CLI 与 API 提供上下文。这直接针对「Agent 写 SQL 看似合理却口径错误」的痛点。对读者：若在做数据 Agent，可先用它统一指标定义，再放开自然语言查询权限。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/01/nvidia-auto-ontology-open-source-semantic-layer-ai-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="juejin-skills-把「自动发文章到掘金」封装成-agent-技能" tabindex="-1">juejin-skills：把「自动发文章到掘金」封装成 Agent 技能 <a class="header-anchor" href="#juejin-skills-把「自动发文章到掘金」封装成-agent-技能" aria-label="Permalink to &quot;juejin-skills：把「自动发文章到掘金」封装成 Agent 技能&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-11-02">2026-11-02</time></p><p>掘金没有官方开放 API，作者用 Node.js 零依赖实现文章发布、图片上传与草稿优先防误发，并封装为可在 Claude Code、Cursor 等 Agent 中调用的通用技能开源（MIT）。文中复盘了接口抓包适配与字节 ImageX 三段式上传细节。对读者：给 Agent 接无官方 API 的平台时，草稿优先 + 幂等校验是避免误发布的必要设计。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7703084122659504128" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="qodo-借-codex-把公司规范注入-ai-代码评审" tabindex="-1">Qodo 借 Codex 把公司规范注入 AI 代码评审 <a class="header-anchor" href="#qodo-借-codex-把公司规范注入-ai-代码评审" aria-label="Permalink to &quot;Qodo 借 Codex 把公司规范注入 AI 代码评审&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-02">2026-11-02</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/12472c224774.png" alt="配图"></p><p>Qodo 将企业知识与编码规范接入 Codex，让开发者在提交 PR 之前就能跨仓库发现 P0 级问题。这类「上下文增强的代码评审」正在成为编码助手的下一个竞争点：不只是补全代码，而是理解团队约定。对读者：引入 AI 评审工具时，优先验证它能否读取你们的内部规范与历史缺陷库，否则误报率会很高。</p><p class="news-entry-source"><a href="https://openai.com/index/qodo-codex-plugin" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const g=a(r,[["render",o]]);export{m as __pageData,g as default};
